import{_ as l,o as i,c as e,a5 as t}from"./chunks/framework.CXroN2RO.js";const P=JSON.parse('{"title":"第11章 GPUアーキテクチャ","description":"","frontmatter":{"title":"第11章 GPUアーキテクチャ","study":{"source":"IT教本","status":"outline","summary":"GPUの実行単位、メモリ階層、並列処理の制約を学び、プロファイラで観察するための学習計画・概要です。CPUとの比較から入り、対象GPUの資料と測定結果を対応させます。\\n\\n## 関連する辞典本文・実践\\n\\n- [GPUとは何か](/hardware/gpu/what-is-gpu.html)と[","section":"learning","format":"path","domain":"hardware","collection":"low-level","order":12}},"headers":[],"relativePath":"guide/low-level/gpu-architecture.md","filePath":"guide/low-level/gpu-architecture.md"}'),r={name:"guide/low-level/gpu-architecture.md"};function n(o,a,s,d,h,u){return i(),e("div",null,[...a[0]||(a[0]=[t(`<div id="第11章-gpuアーキテクチャ-──-多数の処理を並列に進める仕組み" class="study-legacy-anchor" aria-hidden="true"></div><h1 id="第11章-gpuアーキテクチャ" tabindex="-1">第11章 GPUアーキテクチャ <a class="header-anchor" href="#第11章-gpuアーキテクチャ" aria-label="Permalink to &quot;第11章 GPUアーキテクチャ&quot;">​</a></h1><h2 id="このページで案内すること" tabindex="-1">このページで案内すること <a class="header-anchor" href="#このページで案内すること" aria-label="Permalink to &quot;このページで案内すること&quot;">​</a></h2><p>GPUの実行単位、メモリ階層、並列処理の制約を学び、プロファイラで観察するための<strong>学習計画・概要</strong>です。CPUとの比較から入り、対象GPUの資料と測定結果を対応させます。</p><h2 id="関連する辞典本文・実践" tabindex="-1">関連する辞典本文・実践 <a class="header-anchor" href="#関連する辞典本文・実践" aria-label="Permalink to &quot;関連する辞典本文・実践&quot;">​</a></h2><ul><li><a href="/study/hardware/gpu/what-is-gpu.html">GPUとは何か</a>と<a href="/study/hardware/gpu/architecture.html">GPUアーキテクチャ</a>で、構成と役割を調べられます。</li><li><a href="/study/graphics/compute/execution-model.html">Warp / Waveの実行モデル</a>では、並列実行と分岐の扱いを掘り下げます。</li></ul><h2 id="学ぶ理由" tabindex="-1">学ぶ理由 <a class="header-anchor" href="#学ぶ理由" aria-label="Permalink to &quot;学ぶ理由&quot;">​</a></h2><p>シェーダを書き、RenderDocでフレームを追い、描画負荷を最適化するには、 「GPUというハードウェアがCPUと何が違うのか」を知らなければならない。 「ドローコールが多いと重い」「分岐がシェーダで嫌われる」「帯域が足りない」 ── これらの決まり文句は、GPUの実行モデル(SIMT・ワープ・メモリ帯域)を 知って初めて<strong>理由ごと</strong>理解できる。</p><h2 id="到達目標" tabindex="-1">到達目標 <a class="header-anchor" href="#到達目標" aria-label="Permalink to &quot;到達目標&quot;">​</a></h2><ul><li>CPUとGPUの設計思想の違い(レイテンシ指向 vs スループット指向)を説明できる</li><li>SIMT実行モデル(ワープ/ウェーブ、アクティブマスク、分岐ダイバージェンス、同期)を説明できる</li><li>GPUメモリ階層(レジスタ・共有メモリ・VRAM・帯域)を説明できる</li><li>オキュパンシとレイテンシ隠蔽の関係を説明できる</li><li>「CPUバウンド/GPUバウンド」「帯域バウンド/ALUバウンド」を区別できる</li><li>CPU→GPUの接続(PCIe・ドライバ・コマンドバッファ・DMA)を説明できる</li></ul><h2 id="前提知識" tabindex="-1">前提知識 <a class="header-anchor" href="#前提知識" aria-label="Permalink to &quot;前提知識&quot;">​</a></h2><p>第2章(CPU)、第3章(メモリ・キャッシュ)、第8章(OS・ドライバ・DMA)。</p><h2 id="学ぶ内容" tabindex="-1">学ぶ内容 <a class="header-anchor" href="#学ぶ内容" aria-label="Permalink to &quot;学ぶ内容&quot;">​</a></h2><ol><li><strong>設計思想: レイテンシ指向 vs スループット指向</strong><ul><li>CPU: 少数の賢いコア。1本の処理を最速で(分岐予測・OoO・巨大キャッシュ)</li><li>GPU: 数千の単純なALU。100万ピクセルを「まとめて」最速で</li><li>「1ピクセルの処理は遅くていい。全部終わるのが速ければいい」</li></ul></li><li><strong>SIMT実行モデル(最重要)</strong><ul><li>スレッドを束ね、アクティブなレーンへ命令を発行する。NVIDIAのワープは32スレッド。 AMDのウェーブ幅はアーキテクチャ/実行モードによる(32/64等)。暗黙の同期を保証する仕組みではない</li><li><strong>分岐ダイバージェンス</strong>: ワープ内で分岐が割れると両方のパスを 実行してマスクする → シェーダのif文が重くなる条件の正体</li><li>SIMDとの関係: 命令を複数データへ適用する点は似るが、SIMTはthreadごとの 制御フローを表現する。NVIDIA Volta以降にはIndependent Thread Schedulingがあり、 ワープ内が常にロックステップで進む前提の共有メモリ処理は避け、必要な明示同期を使う</li></ul></li><li><strong>GPUの構造</strong><ul><li>SM/CU(実行ユニットのクラスタ)、レジスタファイル、共有メモリ(LDS)</li><li>固定機能ハードウェア: ラスタライザ、テクスチャユニット(フィルタリング)、 ROP(ブレンド・深度)、(近年)RTコア・テンサーコア</li><li>「シェーダコアだけがGPUではない」── 固定機能が massive に働いている</li></ul></li><li><strong>メモリ階層と帯域</strong><ul><li>レジスタ、明示的に使う共有メモリ/LDS、L1/L2キャッシュ、VRAM(GDDR/HBM)。 全てのアクセスがこの順に通るという一本道ではない</li><li><strong>帯域(数百GB/s)こそGPUの生命線</strong>。テクスチャ圧縮(BC/ASTC)や ミップマップが「品質のため」だけでなく「帯域のため」であること</li><li>統合メモリ(コンソール・スマホ・Apple)とディスクリートGPUの違い → コンソール最適化の文脈</li></ul></li><li><strong>レイテンシ隠蔽とオキュパンシ</strong><ul><li>メモリ待ちの間、別のワープに即切り替えて隠す(CPUのOoOに相当する解決策)</li><li>オキュパンシ: 例えばCUDAではSM当たりのアクティブワープ数の最大数に対する割合。 レジスタ/共有メモリ等の使用量に制約される。高いほど必ず速いという指標ではない → 「シェーダのレジスタ数を減らすと速くなる」ことがある理由</li></ul></li><li><strong>CPUからGPUへの道(第13章への橋)</strong><ul><li>ゲーム → API → ユーザーモードドライバ(コマンド生成)→ カーネルモードドライバ → リングバッファ → GPUフロントエンド</li><li>DMA転送、PCIeの帯域、<strong>CPUとGPUは非同期に走る別のコンピュータ</strong></li><li>GPUにも「命令セット」がある(ISAはベンダ毎。シェーダは中間言語 DXIL/SPIR-Vからドライバがコンパイル ← 第12章へ)</li></ul></li><li><strong>性能の切り分け入門(第18章の予習)</strong><ul><li>フレーム時間の二大区分: CPUバウンド / GPUバウンド(判定方法)</li><li>GPU内の区分: 頂点/ピクセル/帯域/ALU/固定機能のどこが詰まるか</li></ul></li></ol><h2 id="重要概念" tabindex="-1">重要概念 <a class="header-anchor" href="#重要概念" aria-label="Permalink to &quot;重要概念&quot;">​</a></h2><ul><li><strong>スループット指向</strong> ── GPU設計のすべてを説明する一語</li><li><strong>ワープ/ウェーブとダイバージェンス</strong> ── シェーダ最適化の基礎文法</li><li><strong>帯域は最も貴重な資源</strong> ── 圧縮・ミップ・フォーマット選択の理由</li><li><strong>レイテンシ隠蔽</strong> ── 「待つ代わりに切り替える」</li><li><strong>CPUとGPUは非同期な別コンピュータ</strong> ── 同期(フェンス)が必要な理由(第13章)</li></ul><h2 id="ゲーム開発との関係" tabindex="-1">ゲーム開発との関係 <a class="header-anchor" href="#ゲーム開発との関係" aria-label="Permalink to &quot;ゲーム開発との関係&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現場の事象</th><th>この章の知識</th></tr></thead><tbody><tr><td>「シェーダで分岐するな」の真偽</td><td>ダイバージェンス(揃った分岐は安い)</td></tr><tr><td>テクスチャ圧縮・ミップマップ必須</td><td>帯域・テクスチャキャッシュ</td></tr><tr><td>解像度を下げたら速くなった</td><td>ピクセル負荷・帯域バウンド</td></tr><tr><td>ドローコール削減・インスタンシング</td><td>CPU→GPUコマンドのコスト(第13章)</td></tr><tr><td>コンソールとPCで最適化が違う</td><td>統合メモリ/ディスクリート</td></tr><tr><td>「GPUバウンドだからCPU最適化は無意味」</td><td>非同期実行・ボトルネック思考</td></tr></tbody></table><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><ol><li>自分のGPUのスペック表(コア数・クロック・帯域)から理論FLOPSと 帯域を計算し、CPUと比較せよ。演算の種類・精度・FMAの数え方を揃え、 理論ピーク比をそのままアプリの速度比としない。</li><li>タスクマネージャ/GPU-Zで、ゲーム実行中のGPU使用率・VRAM・ 各エンジン(3D/Copy)の動きを観察せよ。</li><li>(第12章のシェーダ習得後に戻って)同じ処理を「ワープ内で揃う分岐」と 「ピクセル毎にバラバラの分岐」で書き、フレーム時間を比較せよ。</li><li>非圧縮テクスチャとBC圧縮テクスチャで同じシーンを描画し、 フレーム時間とVRAM使用量を比較せよ(第13章の環境で)。</li><li>「1920x1080、60fps、1ピクセル平均4回のRGBA8参照」を、1参照が4byteの 論理読取りと仮定して概算せよ。1920×1080×60×4×4 = 1,990,656,000byte/s、 約1.99GB/s(十進単位)となる。これは仮定した論理読取量/秒であり、実DRAM帯域の 上限・下限ではない。キャッシュ再利用、フィルタリング、アクセス粒度、圧縮、 overdraw等で実際の転送量は変わる。GPUの測定値と量の定義を揃えて比較する。</li></ol><h2 id="おすすめ書籍" tabindex="-1">おすすめ書籍 <a class="header-anchor" href="#おすすめ書籍" aria-label="Permalink to &quot;おすすめ書籍&quot;">​</a></h2><ul><li>『GPUを支える技術』Hisa Ando ── 和書で唯一級のGPUアーキテクチャ本</li><li>&quot;Real-Time Rendering 4th&quot; 第3章(GPUアーキテクチャ)── 第12章と共用</li><li>Fabian Giesen <strong>&quot;A trip through the Graphics Pipeline 2011&quot;</strong>(ブログ・無料) ── パイプラインをハードウェア視点で解説した伝説の連載。<strong>本章と第12章の主教材</strong></li><li>NVIDIA/AMDのアーキテクチャ・ホワイトペーパー(Ada, RDNA等。無料)</li></ul><h2 id="おすすめoss" tabindex="-1">おすすめOSS <a class="header-anchor" href="#おすすめoss" aria-label="Permalink to &quot;おすすめOSS&quot;">​</a></h2><ul><li><strong>RenderDoc</strong> ── 使い方は第12,18章。ここではインストールだけ</li><li>GPUOpen(AMD)のドキュメント/ISAガイド ── RDNAのISAが公開されている (「GPUにもアセンブリがある」ことを実物で確認)</li><li>tinygrad / llm.c のGPUカーネル ── 計算シェーダの読み物として(発展)</li></ul><h2 id="おすすめ動画" tabindex="-1">おすすめ動画 <a class="header-anchor" href="#おすすめ動画" aria-label="Permalink to &quot;おすすめ動画&quot;">​</a></h2><ul><li>Branch Education &quot;How do GPUs work?&quot; ── CGアニメで見る内部構造(秀逸)</li><li>GDC/CEDECの「GPU最適化」系講演(ベンダ講演: NVIDIA/AMD/コンソール)</li><li>Acerola / kishimisu(シェーダ系YouTube)── 第12章の橋渡し</li></ul><h2 id="読むべきソースコード" tabindex="-1">読むべきソースコード <a class="header-anchor" href="#読むべきソースコード" aria-label="Permalink to &quot;読むべきソースコード&quot;">​</a></h2><ul><li>(ソースの代わりに)AMD GPUOpenの ISA ドキュメントでシェーダの 実アセンブリを眺める</li><li>Radeon GPU Analyzer / NVIDIA Nsightでシェーダのレジスタ数・ISAを見る (第12章のシェーダを書いてから)</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>CPUとGPUの設計思想の違いを「レイテンシ」「スループット」で説明せよ。</li><li>ワープとは何か。分岐ダイバージェンスで何が起きるか。</li><li>GPUはメモリレイテンシをどう隠すか。CPUの方法(OoO・キャッシュ)との違いは?</li><li>テクスチャ圧縮が「画質を犠牲に容量を減らす」以上の意味を持つ理由は?</li><li>オキュパンシとレジスタ数の関係は?</li><li>「GPUバウンド」をどう判定するか(暫定回答でよい。第18章で精密化)。</li><li>CPUが発行した描画コマンドは、どんな経路でGPUに届くか。</li></ol><hr><h2 id="この章がゲームのどこで使われているか" tabindex="-1">この章がゲームのどこで使われているか <a class="header-anchor" href="#この章がゲームのどこで使われているか" aria-label="Permalink to &quot;この章がゲームのどこで使われているか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>フレーム後半戦の主役</span></span>
<span class="line"><span>┌─CPU──────────────┐     ┌─GPU(別のコンピュータ)─────────────┐</span></span>
<span class="line"><span>│ ゲーム更新        │     │ 前フレームの描画を実行中(非同期!)     │</span></span>
<span class="line"><span>│ 描画コマンド生成  ─┼─DMA→│ コマンド読取→頂点→ラスタ→ピクセル    │</span></span>
<span class="line"><span>│ Present呼び出し   │     │ →ROP→フレームバッファ(VRAM)         │</span></span>
<span class="line"><span>└──────────────────┘     └───────────────────────────────────┘</span></span>
<span class="line"><span> 数千ALUが100万ピクセルを並列処理 / 帯域数百GB/sをやりくり</span></span>
<span class="line"><span> ワープ単位でシェーダ実行(第12章) / 完了をフェンスでCPUに通知(第13章)</span></span></code></pre></div><h2 id="記述の確認資料" tabindex="-1">記述の確認資料 <a class="header-anchor" href="#記述の確認資料" aria-label="Permalink to &quot;記述の確認資料&quot;">​</a></h2><ul><li><a href="https://docs.nvidia.com/cuda/cuda-c-best-practices-guide/index.html" target="_blank" rel="noreferrer">NVIDIA CUDA Best Practices: bandwidth / occupancy / branching</a></li><li><a href="https://docs.nvidia.com/cuda/cuda-programming-guide/03-advanced/advanced-kernel-programming.html" target="_blank" rel="noreferrer">NVIDIA CUDA Programming Guide: SIMT / Independent Thread Scheduling</a></li><li><a href="https://gpuopen.com/learn/rdna-performance-guide/" target="_blank" rel="noreferrer">AMD GPUOpen: RDNA Performance Guide</a></li></ul>`,35)])])}const p=l(r,[["render",n]]);export{P as __pageData,p as default};
